j:jelly.script:
addLoadEvent(
	function() {
		if (window['textareaResize'])
			textareaResize('${JS,HTML:jvar_textarea_id}');
		if ($j) {
			var tooltipProperty = {animation: false, container: 'body'};
			$j('#${JS,HTML:jvar_dialog_id}').find('[title]').tooltip(tooltipProperty).hideFix();
			$j('#dialog_buttons').find('button').tooltip(tooltipProperty).hideFix();
		}
	}
);

function enableButton() {
	var notes = "";
	var textArea = $("${JS,HTML:jvar_textarea_id}");
	if (textArea)
		notes = textArea.value.trim();
		var parentDiv = $("element.${JS,HTML:jvar_textarea_id}");
	if (notes $[AND] parentDiv) {
		parentDiv.removeClassName("is-required");
		parentDiv.addClassName("is-filled");
	}
	if (!notes $[AND] parentDiv) {
		parentDiv.removeClassName("is-prefilled");
		parentDiv.removeClassName("is-filled");
		parentDiv.addClassName("is-required");
	}
	var button = $("${JS,HTML:jvar_ok_id}");
	if (notes $[AND] button) {
		button.removeClassName("disabled");
		button.onclick = ${JS,HTML:jvar_ok_action};
	}
	if (!notes $[AND] button) {
		button.addClassName("disabled");
		button.onclick = "";
	}
};
